def C(key,ks,status,statement,cls,fate,refs=(),family='pd',hyp='',computation=None,confidence='high',origin='manuscript',circulation=None,publication=None,reason=''):
    assert key not in claimkeys
    if isinstance(ks,str): ks=[ks]
    ii=[byid[groups[k]] for k in ks]
    ident=f'P56-C{len(claims)+1:03d}';claimkeys[key]=ident
    loc={json.dumps(l,sort_keys=True):l for i in ii for l in i['lines']}
    scans={json.dumps(l,sort_keys=True):l for i in ii for l in i['scans']}
    claims.append(dict(id=ident,items=[i['id'] for i in ii],cote=sorted({c for i in ii for c in i['cote']}),scans=list(scans.values()),lines=list(loc.values()),his_statement=' / '.join(i['his_words'] for i in ii),statement=statement,status_on_pages=status,computation=computation or {'performed':False,'reason':'No finite numerical calculation underlies this statement; the stated scope of textual, theorem or proof checking is recorded in check_events.tsv.'},**{'class':cls},fate=fate,fate_date={'as_of':DATE,'first_circulation':circulation,'publication':publication},present_status=f'As of {DATE}: {fate}',refs=list(refs),confidence=confidence,hypotheses=hyp or 'Exactly the hypotheses in the statement; no unstated extension to arbitrary rings, schemes or coefficient categories.',literature_search_history={'family_id':family,'record':'search_families.json','exact_match_assessment':reason or fate},origin=origin,internal_key=key))
    return ident

